def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    total_opp_def = 0
    total_my_def = 0
    for x in op:
        if x == 'D':
            total_opp_def += 1
    for x in me:
        if x == 'D':
            total_my_def += 1

    last_my = me[-1]
    last_opp = op[-1]

    if total_opp_def == n:
        return 'D'

    if n >= 2 and op[-2] == 'D' and op[-1] == 'D' and (total_opp_def >= 3 or n >= 25):
        return 'D'

    if n >= 15 and total_opp_def >= 4 and total_opp_def * 4 >= n:
        return 'D'

    if total_opp_def == 0 and total_my_def > 0 and n >= 85:
        last_d = -1
        for i in range(n - 1, -1, -1):
            if me[i] == 'D':
                last_d = i
                break
        if last_d >= 0 and last_d <= n - 2:
            return 'D'
        if n == 93 and last_d == 92:
            return 'C'

    if n == 92 and total_opp_def == 0 and total_my_def == 0:
        return 'D'

    if n < 92:
        if last_opp == 'D':
            if last_my == 'C':
                if n >= 2 and me[-2] == 'D':
                    return 'C'
                if total_opp_def >= 2:
                    return 'D'
                return 'C'
            else:
                if total_opp_def >= 5:
                    return 'D'
                return 'C'
        return 'C'

    cnt_c = [0, 0, 0, 0]
    cnt_n = [0, 0, 0, 0]
    rcnt_c = [0, 0, 0, 0]
    rcnt_n = [0, 0, 0, 0]

    recent_start = max(1, n - 20)
    for i in range(1, n):
        a = me[i - 1]
        b = op[i - 1]
        c = op[i]
        ctx = (2 if a == 'D' else 0) + (1 if b == 'D' else 0)

        cnt_n[ctx] += 1
        if c == 'C':
            cnt_c[ctx] += 1

        if i >= recent_start:
            rcnt_n[ctx] += 1
            if c == 'C':
                rcnt_c[ctx] += 1

    if total_opp_def == 0:
        if total_my_def > 0 and n >= 94:
            base = [0.96, 0.92, 0.86, 0.72]
        else:
            base = [0.94, 0.78, 0.48, 0.30]
    elif total_opp_def * 4 >= n:
        base = [0.45, 0.32, 0.24, 0.16]
    elif total_opp_def * 3 >= n:
        base = [0.28, 0.20, 0.14, 0.08]
    else:
        base = [0.84, 0.62, 0.34, 0.20]

    probs = []
    alpha = 8.0
    for s in range(4):
        den = alpha + 2.0 * rcnt_n[s] + cnt_n[s]
        num = alpha * base[s] + 2.0 * rcnt_c[s] + cnt_c[s]
        p = num / den
        if p < 0.04:
            p = 0.04
        elif p > 0.96:
            p = 0.96
        probs.append(p)

    next_val = [0.0, 0.0, 0.0, 0.0]

    for _m in range(99, n, -1):
        curr_val = [0.0, 0.0, 0.0, 0.0]
        for s in range(4):
            pc = probs[s]
            pd = 1.0 - pc

            vc = pc * (3.0 + next_val[0]) + pd * (0.0 + next_val[1])
            vd = pc * (5.0 + next_val[2]) + pd * (1.0 + next_val[3])

            curr_val[s] = vc if vc > vd else vd

        next_val = curr_val

    s = (2 if last_my == 'D' else 0) + (1 if last_opp == 'D' else 0)
    pc = probs[s]
    pd = 1.0 - pc

    vc = pc * (3.0 + next_val[0]) + pd * (0.0 + next_val[1])
    vd = pc * (5.0 + next_val[2]) + pd * (1.0 + next_val[3])

    return 'C' if vc >= vd else 'D'
